  }
}];

// ============================================================
// GHIW-01 Phase 2: Classify Request
// Determines: NEW, EXISTING_BUILDER, IN_PROGRESS, CACHED_REPLAY, DRY_RUN
// ============================================================

const data = $input.first().json;

if (data.route === 'INVALID_REQUEST') {
  data.route = 'RESPOND_ERROR';
  return [{json: data}];
}

if (data.is_dry_run === true) {
  data.route = 'DRY_RUN';
  data.dry_run_result = 'DRY_RUN_APPROVED';
  return [{json: data}];
}

// Proceed to idempotency check first
// For now, set route to CHECK_IDEMPOTENCY
// This will be followed by SSH node to check registry
data.route = 'CHECK_IDEMPOTENCY';
return [{
  json: {
    ...data,
    command: `check-idempotency ${data.idempotency_key}`
  }
}];

// ============================================================
// GHIW-01 Phase 3: Evaluate Idempotency Result
// Parses registry CLI output and determines next action.
// ============================================================

const data = $input.first().json;
const stdout = String($input.first().json.stdout || '');
let registryResult = {};
try { registryResult = JSON.parse(stdout); } catch(e) {}

if (registryResult.status === 'CACHED') {
  // Idempotent replay - return cached result
  return [{
    json: {
      route: 'IDEMPOTENT_REPLAY',
      status: registryResult.result_status || 'IDEMPOTENT_REPLAY',
      correlation_id: data.correlation_id,
      project_id: registryResult.project_id || data.project_id,
      request_id: data.request_id,
      builder_id: registryResult.result_builder_id,
      cached: true,
      timestamp: new Date().toISOString()
    }
  }];
}

// NEW request - continue to check if project already exists
// Read project state from registry
const ensureCmd = `ensure-project ${data.project_id} ${data.request_id} ${data.correlation_id} ${data.idempotency_key} ${data.approval_id} ${data.requested_by} GHIW01-RUN`;

return [{
  json: {
    ...data,
    route: 'ENSURE_PROJECT',
    command: ensureCmd
  }
}];

// ============================================================
// GHIW-01 Phase 4: Analyze Project State & Decide Path
// After ensure-project call, determine: acquire lock, reuse, or error
// ============================================================

const data = $input.first().json;
const stdout = String($input.first().json.stdout || '');
let result = {};
try { result = JSON.parse(stdout); } catch(e) {}

if (result.status === 'EXISTING') {
  // Project already exists in registry
  if (result.active_builder_id && result.current_state === 'BUILDER_READY') {
    return [{
      json: {
        route: 'ALREADY_EXISTS',
        status: 'BUILDER_READY',
        builder_id: result.active_builder_id,
        project_id: result.project_id,
        project_key: result.project_key,
        hostname: result.hostname,
        correlation_id: data.correlation_id,
        request_id: data.request_id,
        current_state: result.current_state,
        node: data.target_node,
        storage: data.target_storage,
        template_id: data.template_id,
        template_version: data.template_version,
        clone_mode: data.clone_mode,
        timestamp: new Date().toISOString()
      }
    }];
  }

  if (['CLONE_PLANNED','CLONING','CLONED','INITIALIZING','STARTING','VERIFYING'].includes(result.current_state)) {
    return [{
      json: {
        route: 'IN_PROGRESS',
        status: 'IN_PROGRESS',
        project_id: result.project_id,
        correlation_id: data.correlation_id,
        request_id: data.request_id,
        current_state: result.current_state,
        timestamp: new Date().toISOString()
      }
    }];
  }

  return [{
    json: {
      route: 'REGISTRY_CONFLICT',
      status: 'FAILED_PRE_READY',
      error_code: 'REGISTRY_STATE_UNEXPECTED',
      project_id: data.project_id,
      correlation_id: data.correlation_id,
      request_id: data.request_id,
      current_state: result.current_state,
      timestamp: new Date().toISOString()
    }
  }];
}

if (result.status === 'CREATED') {
  // New project created - proceed to acquire lock
  return [{
    json: {
      ...data,
      route: 'ACQUIRE_LOCK',
      builder_id: `${data.project_key}-${data.request_id.slice(0, 8)}`,
      created: true
    }
  }];
}

// Error from registry
return [{
  json: {
    route: 'RESPOND_ERROR',
    status: 'FAILED_PRE_READY',
    error_code: result.code || 'REGISTRY_ERROR',
    error_message: result.error || 'Unknown registry error',
    project_id: data.project_id,
    correlation_id: data.correlation_id,
    request_id: data.request_id,
    timestamp: new Date().toISOString()
  }
}];

// ============================================================
// GHIW-01 Phase 5: Response Router
