// ============================================================

const data = $input.first().json;
const route = data.route || 'UNKNOWN';

// Build standard response
const response = {
  ...data,
  timestamp: data.timestamp || new Date().toISOString()
};

// For ALREADY_EXISTS, IDEMPOTENT_REPLAY, DRY_RUN - respond immediately
if (['ALREADY_EXISTS','IDEMPOTENT_REPLAY','DRY_RUN'].includes(route)) {
  response.route = 'RESPOND_SUCCESS';
  return [{json: response}];
}

// For IN_PROGRESS - respond with 202
if (route === 'IN_PROGRESS') {
  response.route = 'RESPOND_ACCEPTED';
  response.status = 'ACCEPTED';
  return [{json: response}];
}

// For errors - respond with error
if (['INVALID_REQUEST','RESPOND_ERROR','REGISTRY_CONFLICT','REGISTRY_ERROR'].includes(route)) {
  response.route = 'RESPOND_ERROR';
  return [{json: response}];
}

// For ACQUIRE_LOCK - continue the provisioning flow
if (route === 'ACQUIRE_LOCK') {
  response.route = 'CONTINUE_PROVISION';
  return [{json: response}];
}

// Default: respond with error
response.route = 'RESPOND_ERROR';
response.error_code = 'UNKNOWN_ROUTE';
return [{json: response}];

