// ============================================================================
// Guardrails: Validate issue state before dispatch
// Check: issue open, agent:ready present, no running/blocked/done
// FIXED: Trigger-agnostic — works with BOTH Manual Trigger AND Schedule Trigger
// ============================================================================

const issueData = $input.first().json;

// Static values for single-repo dispatcher (no dependency on any specific trigger)
const owner = 'xxammaxx';
const repo = 'n8n-blueprint-workflow';
const issueNumber = issueData.number || 0;
const issueTitle = issueData.title || '';
const issueBody = issueData.body || '';
const issueState = issueData.state || 'unknown';
const labels = issueData.labels || [];

const labelNames = labels.map(function(l) { return typeof l === 'string' ? l : l.name; }).filter(Boolean);
const hasReady = labelNames.includes('agent:ready');
const hasRunning = labelNames.includes('agent:running');
const hasBlocked = labelNames.includes('agent:blocked');
const hasDone = labelNames.includes('agent:done');
const needsReview = labelNames.includes('agent:needs-review');
const evidenceAttached = labelNames.includes('evidence:attached');

var mode = 'manual-terminal';
if (labelNames.includes('mode:opencode-run')) mode = 'opencode-run';
else if (labelNames.includes('mode:hermes-review')) mode = 'hermes-review';

var risk = 'medium';
if (labelNames.includes('risk:low')) risk = 'low';
else if (labelNames.includes('risk:high')) risk = 'high';

const isOpen = issueState === 'open';

// HARD BLOCK: Issue #3 is a completed smoke test — never re-process
const isIssue3 = issueNumber === 3;

// Detect already-processed issues (agent:needs-review + evidence:attached = done)
const isAlreadyProcessed = needsReview && evidenceAttached;

const canStart = isOpen && hasReady && !hasRunning && !hasBlocked && !hasDone && !isIssue3 && !isAlreadyProcessed;

const guardResult = {
  owner: owner,
  repo: repo,
  issue_number: issueNumber,
  issue_title: issueTitle,
  issue_body: issueBody,
  issue_url: 'https://github.com/' + owner + '/' + repo + '/issues/' + issueNumber,
  is_open: isOpen,
  has_ready: hasReady,
  has_running: hasRunning,
  has_blocked: hasBlocked,
  has_done: hasDone,
  can_start: canStart,
  mode: mode,
  risk: risk,
  labels: labels,
  label_names: labelNames,
  guardrail: canStart ? 'PASS' : 'BLOCKED',
  guardrail_reason: canStart ? 'Ready to dispatch' : (
    isIssue3 ? 'HARD BLOCK: Issue #3 is a completed smoke test — never re-process' :
    isAlreadyProcessed ? 'Already processed (agent:needs-review + evidence:attached present)' :
    !isOpen ? 'Issue is not open' :
    !hasReady ? 'Missing agent:ready label' :
    hasRunning ? 'agent:running already set — duplicate run blocked' :
    hasBlocked ? 'Issue is blocked' :
    hasDone ? 'Issue already done' : 'Unknown guardrail failure'
  )
};

// Block non-startable issues (but DON'T mutate Error objects — create new error)
if (!canStart) {
  const blockError = new Error('GUARDRAIL_BLOCKED: ' + guardResult.guardrail_reason + ' (issue #' + issueNumber + ')');
  throw blockError;
}

return [{
  json: guardResult
}];

// ============================================================================
// Prepare RUN_INPUT.json from GitHub Issue Data
// Adapted from validated 12-node baseline - uses GitHub API response as input
// ============================================================================

const guardData = $('Guardrails & Validate').first().json;

const owner = String(guardData.owner || 'xxammaxx').trim();
const repo = String(guardData.repo || 'n8n-blueprint-workflow').trim();
const issueNumber = Number(guardData.issue_number || 1);
const mode = String(guardData.mode || 'manual-terminal').trim();

if (!owner) throw new Error('Missing owner');
if (!repo) throw new Error('Missing repo');
if (!Number.isInteger(issueNumber) || issueNumber < 1) throw new Error('Invalid issue_number: ' + issueNumber);

const now = new Date();
const ts = now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
const runId = 'gh-issue-' + issueNumber + '-' + ts;
const issueUrl = 'https://github.com/' + owner + '/' + repo + '/issues/' + issueNumber;

const safeOwner = owner.replace(/[^a-zA-Z0-9_.-]/g, '-');
const safeRepo = repo.replace(/[^a-zA-Z0-9_.-]/g, '-');

const evidenceRoot = '/opt/dev-fabric/evidence/github-agent-runs';
const runInputRemote = evidenceRoot + '/' + safeOwner + '/' + safeRepo + '/issue-' + issueNumber + '/' + runId + '/RUN_INPUT.json';
const evidenceDir = evidenceRoot + '/' + safeOwner + '/' + safeRepo + '/issue-' + issueNumber + '/' + runId;

const runInput = {
  run_id: runId,
  source_of_truth: 'github',
  github: {
    owner: owner,
    repo: repo,
    issue_number: issueNumber,
    issue_url: issueUrl,
    trigger_label: 'agent:ready'
  },
  mode: mode,
  approval_policy: {
    push: false,
    pr: false,
    merge: false,
    github_actions: false,
    provider_config: false
  },
  runner: {
    workspace_root: '/opt/dev-fabric/workspaces/projects',
    evidence_root: evidenceRoot
  },
  agent_runtime: {
    opencode_available: true,
    opencode_version: 'v1.17.9',
    opencode_provider_configured: false,
    hermes_available: false
  }
};

const runInputJson = JSON.stringify(runInput, null, 2);
const runInputB64 = Buffer.from(runInputJson, 'utf-8').toString('base64');

return [{
  json: {
    owner: owner,
    repo: repo,
    issue_number: issueNumber,
    run_id: runId,
    mode: mode,
    issue_url: issueUrl,
    run_input_remote: runInputRemote,
    run_input_b64: runInputB64,
    evidence_dir: evidenceDir,
    guardrail_passed: guardData.can_start,
    labels: guardData.label_names
  }
}];

// ============================================================================
// Format Evidence Comment - SYNCED from Runner status.json
// Reads actual runner evidence via SSH stdout, NOT stale RUN_INPUT.json
// Fallback chain: status.json → SSH raw output → prepData → hardcoded defaults
// ============================================================================

const prepData = $('Prepare RUN_INPUT.json').first().json;
const sshOutput = $input.first().json;

// → Extract evidence path →
const runId = prepData.run_id || 'unknown';
const evidenceDir = prepData.evidence_dir || '/opt/dev-fabric/evidence/github-agent-runs/' + prepData.owner + '/' + prepData.repo + '/issue-' + prepData.issue_number + '/' + runId + '/';

// → Defaults (Priority 3: last resort) →
let status = 'UNKNOWN';
let effectiveMode = prepData.mode || 'manual-terminal';
let providerConfigured = null;
let provider = null;
let model = null;
let openCodeVersion = null;
let evidenceSource = 'fallback (RUN_INPUT.json)';
let exitCodeInfo = 'unknown';

// → Priority 1: Parse status.json from SSH stdout →
let statusData = null;
if (sshOutput && sshOutput.stdout && typeof sshOutput.stdout === 'string') {
  try {
    statusData = JSON.parse(sshOutput.stdout);
  } catch (e) {
    // stdout is not valid JSON - will use fallback
  }
}

if (statusData) {
  evidenceSource = 'status.json';

  // Extract real values from status.json
  status = statusData.status || status;

  if (statusData.mode && statusData.mode.effective) {
    effectiveMode = statusData.mode.effective;
  }

  if (statusData.agent_runtime) {
    if (statusData.agent_runtime.opencode_provider_configured !== undefined) {
      providerConfigured = statusData.agent_runtime.opencode_provider_configured;
    }
    if (statusData.agent_runtime.opencode_version) {
      openCodeVersion = statusData.agent_runtime.opencode_version;
    }
  }

  if (statusData.provider) {
    provider = statusData.provider;
  }

  if (statusData.model) {
    model = statusData.model;
  }

  if (statusData.exit_code !== undefined) {
    exitCodeInfo = String(statusData.exit_code);
  } else if (sshOutput && sshOutput.exitCode !== undefined) {
    exitCodeInfo = String(sshOutput.exitCode);
  }

} else if (sshOutput && sshOutput.stdout) {
  // Priority 2: SSH output available but not parseable JSON
  evidenceSource = 'fallback (SSH raw)';
  if (typeof sshOutput.exitCode !== 'undefined') {
    exitCodeInfo = String(sshOutput.exitCode);
  }
}

// → Fill missing fields with sensible defaults →
if (providerConfigured === null) providerConfigured = false;
if (provider === null) provider = (effectiveMode === 'opencode-run') ? 'deepseek' : 'none';
if (model === null) model = (effectiveMode === 'opencode-run') ? 'deepseek-v4-pro' : 'none';
if (openCodeVersion === null) openCodeVersion = 'unknown';

// → Format comment body →
const commentBody = '## Runner Result\n' +
  '\n' +
  'Status: ' + status + '\n' +
  'Mode: ' + effectiveMode + '\n' +
  'Provider configured: ' + providerConfigured + '\n' +
  'Provider: ' + provider + '\n' +
  'Model: ' + model + '\n' +
  'OpenCode: ' + openCodeVersion + '\n' +
  '\n' +
  'Evidence: ' + evidenceDir + '\n' +
  '\n' +
  'Safety:\n' +
  '- No secrets emitted\n' +
  '- No auto-merge\n' +
  '- No GitHub Actions\n' +
  '\n' +
  '---\n' +
  'Evidence source: ' + evidenceSource;

return [{
  json: {
    owner: prepData.owner,
    repo: prepData.repo,
    issue_number: prepData.issue_number,
    issue_url: prepData.issue_url,
    run_id: runId,
    status: status,
    mode: effectiveMode,
    evidence_dir: evidenceDir,
    comment_body: commentBody,
    evidence_source: evidenceSource
  }
}];

// ============================================================================
// Final Result / Log Output - synced from status.json
// ============================================================================

const prepData = $('Prepare RUN_INPUT.json').first().json;
const evidenceFormat = $('Format Evidence Comment').first().json;

const result = {
  status: evidenceFormat.status || 'GREEN_PARTIAL_PLUS',
  issue_number: prepData.issue_number,
  issue_url: prepData.issue_url,
  run_id: prepData.run_id,
  evidence_dir: prepData.evidence_dir,
  dispatch_mode: evidenceFormat.mode || 'manual-terminal',
  evidence_source: evidenceFormat.evidence_source || 'fallback',
  guardrail_passed: true,
  labels_updated: true,
  comment_posted: true,
  next_action: 'Issue remains open. Human review required. Labels: agent:needs-review + evidence:attached set. OpenCode Provider/Auth + Hermes continue pending.'
};

return [{ json: result }];

// Pick first ready issue from GitHub Search results
const searchResults = $input.first().json;

if (!searchResults || !searchResults.items || searchResults.items.length === 0) {
  // No ready issues - return empty array to stop execution
  return [];
}

const first = searchResults.items[0];
const labelNames = (first.labels || []).map(function(l) { return typeof l === "string" ? l : l.name; }).filter(Boolean);

// Double-check: issue must have agent:ready (Schedule Trigger might fire between search and fetch)
if (!labelNames.includes("agent:ready")) {
  return [];
}

return [{
  json: {
    found: true,
    owner: "xxammaxx",
    repo: "n8n-blueprint-workflow",
    issue_number: first.number,
    issue_title: first.title,
    issue_state: first.state,
    labels: first.labels || [],
    label_names: labelNames,
    html_url: first.html_url
  }
}];

const item = $input.first();
const json = item.json ?? {};
const binary = item.binary ?? {};
const binaryKeys = Object.keys(binary);

function normalizeText(value) {
  return String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function normalizeCheckbox(value, fallback) {
  if (Array.isArray(value)) {
    return value.length > 0;
  }
  if (typeof value === 'boolean') {
    return value;
  }
  if (typeof value === 'string') {
    const lowered = value.trim().toLowerCase();
    if (['true', '1', 'yes', 'on', 'enabled', 'aktiv', 'checked'].includes(lowered)) {
      return true;
    }
    if (['false', '0', 'no', 'off', 'disabled', 'deaktiviert'].includes(lowered)) {
      return false;
    }
  }
  return fallback;
}

function looksBinary(text) {
  const sample = String(text ?? '').slice(0, 4096);
  let suspicious = 0;
  for (const ch of sample) {
    const code = ch.charCodeAt(0);
    if (code === 0) {
      return true;
    }
    if (code < 32 && code !== 9 && code !== 10 && code !== 13) {
      suspicious += 1;
    }
  }
  return suspicious > Math.max(8, Math.floor(sample.length * 0.05));
}

function readBinaryField(fieldName) {
  const entry = binary[fieldName];
  if (!entry || !entry.data) {
    throw new Error(`Binary field ${fieldName} is present but empty.`);
  }
  const decoded = Buffer.from(entry.data, 'base64').toString('utf8');
  return {
    text: normalizeText(decoded),
    filename: entry.fileName || 'BLUEPRINT.md',
    mimeType: entry.mimeType || '',
    fieldName,
  };
}

const projectSlug = String(json.project_slug ?? '').trim();
const projectTitle = String(json.project_title ?? '').trim();
const llmCommandMode = String(json.llm_command_mode ?? 'opencode-run').trim();
const opencodeModel = String(json.opencode_model ?? '').trim();
const maxRuntimeMinutes = Number(json.max_runtime_minutes ?? 60);
const dryRun = normalizeCheckbox(json.dry_run, true);
const allowIssueScript = normalizeCheckbox(json.allow_github_issue_script_generation, true);
const allowGithubActionsFiles = normalizeCheckbox(json.allow_github_actions_files, true);
const extraInstruction = normalizeText(json.extra_instruction ?? '');

if (!/^[a-z0-9][a-z0-9-]{1,60}[a-z0-9]$/.test(projectSlug)) {
  throw new Error('project_slug darf nur Kleinbuchstaben, Zahlen und Bindestriche enthalten und muss 3ÔÇô62 Zeichen lang sein.');
}
if (projectTitle.length < 3 || projectTitle.length > 120) {
  throw new Error('project_title muss 3 bis 120 Zeichen lang sein.');
}
if (!['opencode-run', 'hermes-run', 'manual-terminal'].includes(llmCommandMode)) {
  throw new Error('llm_command_mode muss opencode-run, hermes-run oder manual-terminal sein.');
}
if (!Number.isInteger(maxRuntimeMinutes) || maxRuntimeMinutes < 5 || maxRuntimeMinutes > 180) {
  throw new Error('max_runtime_minutes muss eine ganze Zahl zwischen 5 und 180 sein.');
}

let blueprintSource = 'textarea';
let blueprintFilename = 'BLUEPRINT.md';
let blueprintMarkdown = '';

if (binary.blueprint_file && binary.blueprint_file.data) {
  const file = readBinaryField('blueprint_file');
  blueprintSource = 'file';
  blueprintFilename = file.filename || 'BLUEPRINT.md';
  blueprintMarkdown = file.text;
} else if (binaryKeys.length === 1) {
  const file = readBinaryField(binaryKeys[0]);
  blueprintSource = 'file';
  blueprintFilename = file.filename || 'BLUEPRINT.md';
  blueprintMarkdown = file.text;
} else if (binaryKeys.length > 1) {
  throw new Error('Mehrere Binary-Felder vorhanden, aber keines hei├ƒt blueprint_file. Bitte genau ein Blueprint-File hochladen oder blueprint_file verwenden.');
} else {
  const text = normalizeText(json.blueprint_text ?? '');
  if (!text.trim()) {
    throw new Error('Bitte BLUEPRINT.md hochladen oder Blueprint als Markdown-Text einf├╝gen.');
  }
  blueprintMarkdown = text;
}

blueprintMarkdown = normalizeText(blueprintMarkdown);
if (blueprintMarkdown.length < 50) {
  throw new Error('Blueprint muss mindestens 50 Zeichen enthalten.');
}
if (blueprintMarkdown.length > 300000) {
  throw new Error('Blueprint ├╝berschreitet die maximale L├ñnge von 300000 Zeichen.');
}
if (looksBinary(blueprintMarkdown)) {
  throw new Error('Blueprint enth├ñlt offensichtlich Bin├ñrdaten und wird abgelehnt.');
}

const runId = `run-${new Date().toISOString().replace(/[-:]/g, '').replace(/\.[0-9]{3}Z$/, 'Z')}-${Math.floor(Math.random() * 16777216).toString(16).padStart(6, '0')}`;
const projectDir = `/opt/dev-fabric/workspaces/projects/${projectSlug}`;
const runDir = `/opt/dev-fabric/evidence/blueprint-bootstrap/${projectSlug}/${runId}`;
const logDir = `/opt/dev-fabric/logs/blueprint-bootstrap/${projectSlug}/${runId}`;
const blueprintSha256 = Array.from(new TextEncoder().encode(blueprintMarkdown)).reduce((h, b) => ((h << 5) - h + b) | 0, 5381).toString(16);
const blueprintB64 = Buffer.from(blueprintMarkdown, 'utf8').toString('base64');
const initPromptB64 = '';
const extraInstructionB64 = extraInstruction ? Buffer.from(extraInstruction, 'utf8').toString('base64') : '';
const runInputFilename = `RUN_INPUT-${runId}.json`;
const uploadDir = '/tmp';
const finalInputPath = `${runDir}/RUN_INPUT.json`;
const statusPath = `${runDir}/status.json`;
const reportPath = `${runDir}/run-report.md`;
const agentLogPath = `${runDir}/agent.log`;
const shellQuote = (value) => JSON.stringify(String(value));
const startCommand = `set -euo pipefail && mkdir -p ${shellQuote(runDir)} ${shellQuote(logDir)} && mv ${shellQuote(`${uploadDir}/${runInputFilename}`)} ${shellQuote(finalInputPath)} && chmod 600 ${shellQuote(finalInputPath)} && ${shellQuote('/opt/dev-fabric/scripts/start_blueprint_bootstrap.sh')} --input-json ${shellQuote(finalInputPath)}`;
const readStatusCommand = `bash -lc ${shellQuote(`if [ -f ${shellQuote(statusPath)} ]; then jq -c . ${shellQuote(statusPath)}; else printf '%s\\n' ${shellQuote(JSON.stringify({ status: 'PENDING', message: 'status.json not written yet', run_dir: runDir }))}; fi`)}`;
const tailCommand = `tail -f ${agentLogPath}`;
const stopCommand = `tmux kill-session -t <session_name>`;
const attachCommand = `ssh runner@192.168.1.53\ntmux attach -t <session_name>`;
const reportCommand = `cat ${reportPath}`;
const redactedSummary = {
  project_slug: projectSlug,
  project_title: projectTitle,
  run_id: runId,
  blueprint_source: blueprintSource,
  blueprint_filename: blueprintFilename,
  blueprint_sha256: blueprintSha256,
  blueprint_length: blueprintMarkdown.length,
  llm_command_mode: llmCommandMode,
  opencode_model_present: Boolean(opencodeModel),
  max_runtime_minutes: maxRuntimeMinutes,
  dry_run: dryRun,
  allow_github_issue_script_generation: allowIssueScript,
  allow_github_actions_files: allowGithubActionsFiles,
  extra_instruction_present: Boolean(extraInstruction.trim()),
  blueprint_binary_field_count: binaryKeys.length,
};

return [{
  json: {
    project_slug: projectSlug,
    project_title: projectTitle,
    run_id: runId,
    project_dir: projectDir,
    run_dir: runDir,
    log_dir: logDir,
    blueprint_source: blueprintSource,
    blueprint_filename: blueprintFilename,
    blueprint_sha256: blueprintSha256,
    blueprint_length: blueprintMarkdown.length,
    blueprint_b64: blueprintB64,
    blueprint_markdown: blueprintMarkdown,
    init_prompt_b64: initPromptB64,
    llm_command_mode: llmCommandMode,
    opencode_model: opencodeModel,
    max_runtime_minutes: maxRuntimeMinutes,
    dry_run: dryRun,
    allow_github_issue_script_generation: allowIssueScript,
    allow_github_actions_files: allowGithubActionsFiles,
    extra_instruction_b64: extraInstructionB64,
    redacted_summary: redactedSummary,
    run_input_filename: runInputFilename,
    upload_dir: uploadDir,
    start_command: startCommand,
    read_status_command: readStatusCommand,
    attach_command: attachCommand,
    tail_command: tailCommand,
    stop_command: stopCommand,
    report_command: reportCommand,
    status_path: statusPath,
    report_path: reportPath,
    agent_log_path: agentLogPath,
  },
}];

const input = $input.first().json;
const runInput = {
  project_slug: input.project_slug,
  project_title: input.project_title,
  run_id: input.run_id,
  project_dir: input.project_dir,
  run_dir: input.run_dir,
  log_dir: input.log_dir,
  blueprint_source: input.blueprint_source,
  blueprint_filename: input.blueprint_filename,
  blueprint_sha256: input.blueprint_sha256,
  blueprint_length: input.blueprint_length,
  blueprint_b64: input.blueprint_b64,
  init_prompt_b64: input.init_prompt_b64,
  llm_command_mode: input.llm_command_mode,
  opencode_model: input.opencode_model,
  max_runtime_minutes: input.max_runtime_minutes,
  dry_run: input.dry_run,
  allow_github_issue_script_generation: input.allow_github_issue_script_generation,
  allow_github_actions_files: input.allow_github_actions_files,
  extra_instruction_b64: input.extra_instruction_b64,
};

const runInputJson = JSON.stringify(runInput, null, 2) + '\n';
const binaryData = {
  data: Buffer.from(runInputJson, 'utf8').toString('base64'),
  mimeType: 'application/json',
  fileName: input.run_input_filename,
};

return [{
  json: {
    ...input,
    run_input_json_size: Buffer.byteLength(runInputJson, 'utf8'),
    run_input_upload_path: input.upload_dir,
  },
  binary: {
    run_input_json: binaryData,
  },
}];

const prepared = $node["Prepare RUN_INPUT"].json;
const statusItem = $input.first().json ?? {};
const rawStatus = typeof statusItem.stdout === 'string' ? statusItem.stdout.trim() : '';
let statusJson = {};
if (rawStatus) {
  try {
    statusJson = JSON.parse(rawStatus);
