state.preflight_repo_reachable = repo_reachable;
state.preflight_repo_identity = repo_identity;
state.preflight_state = repo_reachable ? 'REPO_REACHABLE' : 'REPO_UNREACHABLE';

return [{ json: state }];

// GHIW-00 PREFLIGHT: Check Builder Capacity
const state = $input.first().json;

// Query registry for available CTIDs
const available_ctids = 1;  // CT 8001 exists and is BUILDER_READY
const ctid_range = { min: 8001, max: 8999 };

state.preflight_capacity = available_ctids;
state.preflight_ctid_range = ctid_range;
state.preflight_state = available_ctids > 0 ? 'CAPACITY_OK' : 'CAPACITY_EXHAUSTED';

return [{ json: state }];

// GHIW-00 PREFLIGHT: Check Mutation Policy & ensure_builder_enabled
const state = $input.first().json;

// Read provisioner config (simulated for Shadow Mode)
const live_mutations_enabled = true;
const ensure_builder_enabled = false;  // ← SAFETY GATE

state.preflight_live_mutations = live_mutations_enabled;
state.preflight_ensure_builder_enabled = ensure_builder_enabled;

// ensure_builder_enabled=false is DEGRADED, not BLOCK
if (!ensure_builder_enabled) {
  state.preflight_state = 'DEGRADED_ENSURE_BUILDER_DISABLED';
} else {
  state.preflight_state = 'POLICY_OK';
}

return [{ json: state }];

// GHIW-00: Assemble Preflight Decision
// Deterministic ALLOW/BLOCK/DEGRADED output.
// SHADOW MODE: decision is logged, existing GHIW-01 flow continues unchanged.

const state = $input.first().json;

const checks = {
  github_auth: state.preflight_github_auth || false,
  n8n_auth: state.preflight_n8n_auth || false,
  repo_reachable: state.preflight_repo_reachable || false,
  capacity_ok: (state.preflight_capacity || 0) > 0,
  ensure_builder_enabled: state.preflight_ensure_builder_enabled || false
};

let decision = 'ALLOW';
let reason_codes = ['ALL_PREFLIGHT_GATES_PASS'];

// BLOCK conditions
if (!checks.github_auth) {
  decision = 'BLOCK';
  reason_codes = ['GITHUB_AUTH_FAILED'];
} else if (!checks.n8n_auth) {
  decision = 'BLOCK';
  reason_codes = ['N8N_AUTH_FAILED'];
} else if (!checks.repo_reachable) {
  decision = 'BLOCK';
  reason_codes = ['REPO_UNREACHABLE'];
} else if (!checks.capacity_ok) {
  decision = 'BLOCK';
  reason_codes = ['BUILDER_CAPACITY_EXHAUSTED'];
} else if (!checks.ensure_builder_enabled) {
  decision = 'DEGRADED';
  reason_codes = ['ENSURE_BUILDER_DISABLED', 'DEGRADED_BUT_OPERABLE'];
}

const preflight_result = {
  schema_version: '1.0',
  decision,
  reason_codes,
  capabilities: checks,
  preflight_timestamp: new Date().toISOString(),
  shadow_mode: true
};

// SHADOW: Log decision but continue existing flow
return [{
  json: {
    ...state,
    preflight_result,
    current_state: decision === 'BLOCK' ? 'BLOCKED' : state.current_state
  }
}];

// === After Lock Health ===
const prev = $('Initialize State').item.json;
const ssh = $input.first().json;
try {
  const r = JSON.parse(ssh.result || ssh.stdout || '{}');
  if (r.status !== 'ok') {
    return [{ json: { ...prev, status:"BLOCKED", error:{code:"LOCK_UNHEALTHY"}, current_state:"BLOCKED", command:"" } }];
  }
  // Prepare acquire command
  const acquireJson = JSON.stringify({schema_version:"1.0", lock_key:prev.lock_key, lock_type:"project-builder", repo_hash:prev.repo_hash, run_id:prev.run_id, ttl_seconds:300});
  const cmd = "ghiw-lock-v1 acquire " + (function toB64(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); })(acquireJson);
  return [{ json: { ...prev, lock_healthy:true, current_state:"LOCK_WAIT", command:cmd } }];
} catch(e) {
  return [{ json: { ...prev, status:"FAILED", error:{code:"LOCK_HEALTH_PARSE_ERROR",message:e.message}, current_state:"FAILED", command:"" } }];
}

// === After Acquire Lock ===
let prev;
try { prev = $('After Lock Health').item.json; } catch(e) { prev = $input.first().json; }
const ssh = $input.first().json;
try {
  const r = JSON.parse(ssh.result || ssh.stdout || '{}');
  if (r.status === 'ok' || r.status === 'acquired') {
    return [{ json: { ...prev, lock_acquired:true, lease_token:r.lease_token, lock_generation:r.generation, lock_expires_at:r.expires_at, current_state:"LOCK_ACQUIRED", command:"" } }];
  }
  return [{ json: { ...prev, status:"BLOCKED", error:{code:"LOCK_ACQUIRE_FAILED",message:JSON.stringify(r.error||r)}, current_state:"BLOCKED", command:"" } }];
} catch(e) {
  return [{ json: { ...prev, status:"FAILED", error:{code:"LOCK_ACQUIRE_PARSE_ERROR",message:e.message}, current_state:"FAILED", command:"" } }];
}

// === Prepare Provisioner Health ===
const prev = $('After Acquire').item.json;
if (prev.status && prev.status !== "LOCK_ACQUIRED") return [{ json: { ...prev, command:"" } }];
const healthJson = JSON.stringify({schema_version:"1.0"});
const cmd = "ghiw-provisioner-v1 health " + (function toB64(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); })(healthJson);
return [{ json: { ...prev, current_state:"RECONCILING", command:cmd } }];

// === After Provisioner Health ===
const prev = $('Prepare Prov Health').item.json;
const ssh = $input.first().json;
try {
  const r = JSON.parse(ssh.result || ssh.stdout || '{}');
  if (r.status === 'ok' && r.data) {
    if (r.data.live_mutations_enabled !== false) {
      return [{ json: { ...prev, status:"BLOCKED", error:{code:"MUTATIONS_ENABLED"}, current_state:"BLOCKED", command:"" } }];
    }
    return [{ json: { ...prev, prov_healthy:true, live_mutations_enabled:false, prov_state:r.data, current_state:"RECONCILING", command:"" } }];
  }
  return [{ json: { ...prev, status:"FAILED", error:{code:"PROVISIONER_UNHEALTHY",message:JSON.stringify(r)}, current_state:"FAILED", command:"" } }];
} catch(e) {
  return [{ json: { ...prev, status:"FAILED", error:{code:"PROV_HEALTH_PARSE_ERROR",message:e.message}, current_state:"FAILED", command:"" } }];
}

// === Prepare Plan-Ensure-Builder ===
const prev = $('After Prov Health').item.json;
if (prev.status && prev.status !== "RECONCILING") return [{ json: { ...prev, command:"" } }];
const planJson = JSON.stringify({schema_version:"1.0", run_id:prev.run_id, project_key:prev.project_key, repo_hash:prev.repo_hash, project_id:prev.project_id, repository:prev.repository, mutation_approval_id:(prev.mutation_approval_id || "e3r1-dry-run-" + prev.run_id.slice(0,8)), requested_capabilities:prev.requested_capabilities, dry_run:true});
const cmd = "ghiw-provisioner-v1 plan-ensure-builder " + (function toB64(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); })(planJson);
return [{ json: { ...prev, current_state:"PLAN_REQUESTED", command:cmd } }];

// === After Plan Ensure Builder ===
const prev = $('Prepare Plan').item.json;
const ssh = $input.first().json;
try {
  const r = JSON.parse(ssh.result || ssh.stdout || '{}');
  if (r.status !== 'ok' || !r.data) {
    return [{ json: { ...prev, status:"FAILED", error:{code:"PLAN_FAILED",message:JSON.stringify(r.error||r)}, current_state:"FAILED", command:"" } }];
  }
  const plan = r.data;
  if (plan.template_id !== 'ct109') return [{ json: { ...prev, status:"BLOCKED", error:{code:"WRONG_TEMPLATE"}, command:"" } }];
  if (plan.clone_mode !== 'linked') return [{ json: { ...prev, status:"BLOCKED", error:{code:"FULL_CLONE_BLOCKED"}, command:"" } }];
  if (plan.storage !== 'sata-local') return [{ json: { ...prev, status:"BLOCKED", error:{code:"WRONG_STORAGE"}, command:"" } }];
  if (plan.ctid === 8000) return [{ json: { ...prev, status:"BLOCKED", error:{code:"CTID_8000_BLOCKED"}, command:"" } }];
  if (plan.ctid < 8001 || plan.ctid > 8999) return [{ json: { ...prev, status:"BLOCKED", error:{code:"CTID_OUT_OF_RANGE"}, command:"" } }];
  if (plan.mutations_live === true) return [{ json: { ...prev, status:"BLOCKED", error:{code:"MUTATIONS_WOULD_BE_LIVE"}, command:"" } }];
  return [{ json: { ...prev, plan, plan_valid:true, planned_ctid:plan.ctid, planned_hostname:plan.hostname, fingerprint_match:plan.fingerprint_match, scope_guard:plan.scope_guard, registry_writes:plan.registry_writes||0, proxmox_writes:plan.proxmox_writes||0, current_state:"PLAN_RECEIVED", command:"" } }];
} catch(e) {
  return [{ json: { ...prev, status:"FAILED", error:{code:"PLAN_PARSE_ERROR",message:e.message}, current_state:"FAILED", command:"" } }];
}

// === Prepare Registry Verification ===
const prev = $('After Plan').item.json;
if (prev.status && prev.status !== "PLAN_RECEIVED") return [{ json: { ...prev, command:"" } }];
const healthJson = JSON.stringify({schema_version:"1.0"});
const cmd = "ghiw-provisioner-v1 health " + (function toB64(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); })(healthJson);
return [{ json: { ...prev, current_state:"VERIFYING", command:cmd } }];

// === After Registry Verification ===
const prev = $('Prepare Verify').item.json;
const ssh = $input.first().json;
try {
  const r = JSON.parse(ssh.result || ssh.stdout || '{}');
  if (r.status === 'ok' && r.data) {
    if (r.data.projects !== 0 || r.data.builders !== 0) {
      return [{ json: { ...prev, status:"RED_GHIW_REGISTRY_DIVERGENCE", error:{code:"UNEXPECTED_MUTATION"}, command:"" } }];
    }
    return [{ json: { ...prev, registry_verified:true, registry_mutated:false, proxmox_mutated:false, current_state:"DRY_RUN_READY", command:"" } }];
  }
  return [{ json: { ...prev, status:"FAILED", error:{code:"VERIFY_FAILED",message:JSON.stringify(r)}, command:"" } }];
} catch(e) {
  return [{ json: { ...prev, status:"FAILED", error:{code:"VERIFY_PARSE_ERROR",message:e.message}, command:"" } }];
}

// === Prepare Lock Release ===
const prev = $('After Verify').item.json;
if (!prev.lease_token && !prev.lock_acquired) {
  return [{ json: { ...prev, lock_released:false, current_state:"RELEASING_LOCK", command:"" } }];
}
const releaseJson = JSON.stringify({schema_version:"1.0", lock_key:prev.lock_key, run_id:prev.run_id, lease_token:prev.lease_token, generation:prev.lock_generation});
const cmd = "ghiw-lock-v1 release " + (function toB64(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); })(releaseJson);
return [{ json: { ...prev, current_state:"RELEASING_LOCK", command:cmd } }];

// === After Lock Release ===
let prev;
try { prev = $('Prepare Release').item.json; } catch(e) { prev = $input.first().json; }
const ssh = $input.first().json;
try {
  const r = JSON.parse(ssh.result || ssh.stdout || '{}');
  return [{ json: { ...prev, lock_released: r.status === 'ok' || r.status === 'released', current_state:"COMPLETED", command:"" } }];
} catch(e) {
  return [{ json: { ...prev, lock_released:true, current_state:"COMPLETED", command:"" } }];
}

// === Assemble Final Output Contract ===
let state;
try { state = $('After Release').item.json; } catch(e) { state = $input.first().json; }

const isError = state.status && state.status !== "COMPLETED" && state.status !== "DRY_RUN_READY" && state.status !== "LOCK_ACQUIRED" && state.status !== "RECONCILING" && state.status !== "PLAN_REQUESTED" && state.status !== "PLAN_RECEIVED" && state.status !== "VERIFYING" && state.status !== "RELEASING_LOCK";

if (isError) {
