    lock:{released:state.lock_released||false, generation:state.lock_generation||0},
    registry_mutated:false, proxmox_mutated:false, errors:[state.error]
  }}];
}

return [{ json: {
  schema_version:"1.0", run_id:state.run_id, request_id:state.request_id,
  status:"success", mode:"dry_run",
  project_id:state.project_id, project_key:state.project_key,
