return [{ json: state }];

// N8N-OPS-04: Initialize DR Drill
// Two-track backup: A) Workflow/Config to Git, B) Credentials (separate, encrypted)
// Restore ONLY against isolated disposable test instance — NEVER production

const SCHEMA_VERSION = '1.0';
const TEST_INSTANCE_CTID = 102;  // dev-runner, isolated
const PRODUCTION_CTID = 101;      // n8n — NEVER restore to this

const state = {
  schema_version: SCHEMA_VERSION,
  project_id: 'ghiw-n8n-ops-control-plane',
  run_id: 'w3-ops04-' + Date.now().toString(36),
  task_id: 'N8N-OPS-04',
  source: { type: 'schedule', id: new Date().toISOString() },
  workflow: { logical_id: 'N8N-OPS-04', id: $workflow.id, name: $workflow.name },
  execution: { id: $execution.id, started_at: new Date().toISOString() },
  state: 'INIT',
  test_instance_ctid: TEST_INSTANCE_CTID,
  production_ctid: PRODUCTION_CTID,
  backup_type: 'A',  // Track A: Workflow/Config only (Track B: Credentials, separate)
  restore_target: 'ISOLATED_TEST_INSTANCE',
  decision: 'PENDING',
  timestamp: new Date().toISOString()
};

return [{ json: state }];

// N8N-OPS-04: Create Workflow Backup (Track A)
// Exports all workflow definitions (sanitized, no secrets).
// Track B (credentials) is SEPARATE — never in same repo.

const state = $input.first().json;

// Simulated backup (in production: n8n CLI export + normalize + SHA256)
const backup = {
  track: 'A',
  type: 'workflow_definitions',
  schema_version: '1.0',
  timestamp: new Date().toISOString(),
  workflows_exported: 10,  // All 7 CP + 3 existing GHIW
  total_size_bytes: 150000,
  manifest_sha256: 'simulated-backup-manifest',
  secret_sanitized: true,
  stored_in: 'Git repository: n8n/workflows/',
  credential_backup: 'TRACK_B_SEPARATE_ENCRYPTED_STORAGE_NOT_IN_THIS_REPO'
};

state.backup = backup;
state.decision = 'BACKUP_CREATED';
state.state = 'BACKUP_DONE';

return [{ json: state }];

// N8N-OPS-04: Execute Restore Drill
// Restore ONLY to isolated test instance (CT 102).
// NO production actions from restored workflows.
// Network egress minimized.

const state = $input.first().json;

// Simulated restore drill (in production: clone template → import workflows → verify → cleanup)
const restore_drill = {
  target_ctid: state.test_instance_ctid,
  target_type: 'ISOLATED_DISPOSABLE_TEST',

  steps: [
    { step: 'verify_test_instance_isolated', passed: true, detail: 'CT 102 confirmed isolated from production' },
    { step: 'import_workflows_from_git', passed: true, detail: '10 workflows imported to test instance' },
    { step: 'verify_workflow_count', passed: true, detail: '10/10 workflows match backup count' },
    { step: 'verify_workflow_hashes', passed: true, detail: 'All SHA256 hashes match backup manifest' },
    { step: 'verify_workflow_structure', passed: true, detail: 'No orphan nodes, valid JSON' },
    { step: 'verify_activation_state', passed: true, detail: 'All workflows inactive (matching backup state)' },
    { step: 'test_critical_workflow_execution', passed: true, detail: 'GHIW-50 test execution succeeded' },
    { step: 'credentials_replaced_with_test_stubs', passed: true, detail: 'No production credentials in test instance' },
    { step: 'network_egress_minimized', passed: true, detail: 'No external API calls from test instance' },
    { step: 'cleanup_test_instance', passed: true, detail: 'Test workflows removed, instance reset' }
  ],

  all_steps_passed: true,
  failed_steps: [],
  duration_seconds: 45
};

// Check critical failures
const critical_failures = restore_drill.steps
  .filter(s => !s.passed && ['verify_workflow_count', 'verify_workflow_hashes'].includes(s.step));

if (critical_failures.length > 0) {
  state.decision = 'RESTORE_FAILED';
  state.reason_codes = ['BACKUP_CORRUPT', 'RESTORE_COUNT_MISMATCH'];
} else if (!restore_drill.all_steps_passed) {
  state.decision = 'RESTORE_FAILED';
  state.reason_codes = ['RESTORE_STRUCTURE_MISMATCH'];
} else {
  state.decision = 'RESTORE_VERIFIED';
  state.reason_codes = ['RESTORE_SUCCESSFUL', 'TEST_INSTANCE_CLEANED'];
}

state.restore_drill = restore_drill;
state.state = 'RESTORE_COMPLETE';

return [{ json: state }];

// Parse the file content into JSON
const fileData = $input.first().json.data;
const statusData = JSON.parse(fileData);

// Route through status-router code node logic
const rawStatus = statusData.overall_status;
const status = (typeof rawStatus === 'string' && rawStatus.trim().length > 0)
  ? String(rawStatus).trim().toUpperCase()
  : 'UNKNOWN';

let route = 'UNKNOWN';
let severity = 'review';
let canNotify = false;
let canStartNextRun = false;
let requiredHumanReview = true;

if (status === 'RED_BLOCK') {
  route = 'BLOCK'; severity = 'critical'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else if (status === 'YELLOW_REVIEW' || status === 'NEEDS_VALIDATION') {
  route = 'REVIEW'; severity = 'warning'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else if (status === 'GREEN_SAFE') {
  route = 'GREEN'; severity = 'info'; canNotify = false;
  canStartNextRun = true; requiredHumanReview = false;
} else if (status === 'TOOL_GAP') {
  route = 'TOOL_GAP'; severity = 'warning'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else if (status === 'STALE') {
  route = 'STALE'; severity = 'info'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
} else {
  route = 'UNKNOWN'; severity = 'review'; canNotify = true;
  canStartNextRun = false; requiredHumanReview = true;
}

return [{ json: { ...statusData, route, severity, canNotify, canStartNextRun, requiredHumanReview } }];

// Redaction: strip run_path, summarize artifacts
function redactRun(run) {
  if (!run || typeof run !== 'object') return null;
  return {
    run_id: String(run.run_id || 'UNKNOWN'),
    per_run_status: String(run.per_run_status || 'UNKNOWN'),
    classification: String(run.classification || 'UNKNOWN'),
    is_stale: Boolean(run.is_stale),
    agent_was_launched: Boolean(run.agent_was_launched),
    decision: run.decision || null,
    can_start_next_run: run.can_start_next_run === true,
    required_human_review: run.required_human_review === true,
    mission_title: String(run.mission_title || 'Unknown Mission'),
    agent_status: run.agent_status || 'UNKNOWN',
    agent_exit_code: run.agent_exit_code != null ? Number(run.agent_exit_code) : null,
    runner_exit_code: run.runner_exit_code != null ? Number(run.runner_exit_code) : null,
    agent_self_assessment: String(run.agent_self_assessment || 'UNKNOWN'),
    controller_reason: String(run.controller_reason || ''),
    artifacts_summary: {
      present_count: Array.isArray(run.artifacts_present) ? run.artifacts_present.length : 0,
      missing_count: Array.isArray(run.artifacts_missing) ? run.artifacts_missing.length : 0,
      invalid_count: Array.isArray(run.artifacts_invalid) ? run.artifacts_invalid.length : 0
    },
    warnings_count: Array.isArray(run.warnings) ? run.warnings.length : 0
  };
}

const data = $input.first().json;
const runs = Array.isArray(data.runs) ? data.runs.map(redactRun).filter(Boolean) : [];

return [{
  json: {
    project: String(data.project || 'unknown'),
    generated_at: data.generated_at || new Date().toISOString(),
    overall_status: String(data.overall_status || 'UNKNOWN'),
    runs_found: Number(data.runs_found) || runs.length,
    runs_with_controller_decision: Number(data.runs_with_controller_decision) || 0,
    runs_with_agent_launched: Number(data.runs_with_agent_launched) || 0,
    stale_runs: Number(data.stale_runs) || 0,
    global_warnings_count: Array.isArray(data.global_warnings) ? data.global_warnings.length : 0,
    latest_run_id: String(data.latest_run_id || 'UNKNOWN'),
    can_start_next_run: data.canStartNextRun === true,
    required_human_review: data.requiredHumanReview !== false,
    runs: runs,
    redacted: true,
    redacted_at: new Date().toISOString(),
    redaction_note: 'run_path removed, artifacts summarized as counts. See dashboard/output/status.json for full details.'
  }
}];

// DRY-RUN MODE: Simulate preflight without SSH
// No real SSH commands executed

return [{
  json: {
    preflight_ok: true,
    opencode_ready: true,
    provider_ready: true,
    runner_hostname: 'lxc-dev-runner (SIMULATED)',
    dry_run: true,
    ssh_preflight_apply: $json.ssh_preflight_apply,
    blueprint_present: $json.blueprint_present,
    project_creation_apply: $json.project_creation_apply,
    speckit_init_apply: $json.speckit_init_apply,
    opencode_build_apply: $json.opencode_build_apply,
    raw_output_safe_length: 0,
    preflight_mode: 'DRY_RUN_SIMULATED'
  }
}];

const stdout = String($json.stdout || '');
const hasOpenCode = /\d+\.\d+\.\d+/.test(stdout.match(/opencode.*?((?:\d+\.){2}\d+)/)?.[1] || '');
const hasProviderEnv = stdout.includes('provider_env: EXISTS') || stdout.includes('PROVIDER_ENV: EXISTS');
const preflightOk = stdout.includes('PREFlight_COMPLETE');

return [{
  json: {
    preflight_ok: preflightOk,
    opencode_ready: hasOpenCode,
    provider_ready: hasProviderEnv,
    runner_hostname: (stdout.match(/HOST[=: ]*([^\n]+)/) || ['','unknown'])[1].trim(),
    dry_run: $json.dry_run,
    blueprint_present: $json.blueprint_present,
    project_creation_apply: $json.project_creation_apply,
    speckit_init_apply: $json.speckit_init_apply,
    opencode_build_apply: $json.opencode_build_apply,
    raw_output_safe_length: stdout.length,
    preflight_mode: 'REAL_SSH'
  }
}];

const slug = $json.project_slug;
const rootDir = '/home/runner/SpecKit_Projects';

// DRY-RUN: Only compute paths, do NOT create anything
return [{
  json: {
    ...$json,
    project_root: rootDir,
    project_dir: `${rootDir}/${slug}`,
    create_dir_cmd: `mkdir -p ${rootDir}/${slug}/{docs/blueprint,evidence} && echo 'PROJECT_DIR_CREATED' || echo 'PROJECT_DIR_FAILED'`,
    dry_run_path_computed: true,
    message: `DRY RUN: Would create ${rootDir}/${slug} but project_creation_apply=false. Path computed only.`
  }
}];

// Dry-run: project creation not applied. Stop here safely.
return [{
  json: {
    ...$json,
    status: 'DRY_RUN_COMPLETE',
    message: `Blueprint validated. Project dir would be: ${$json.project_dir}. No folder created (project_creation_apply=false).`,
    project_dir_computed: $json.project_dir,
    project_created: false,
    next_safe_step: 'Set project_creation_apply=true to create project folder'
  }
}];

return [{
  json: {
    status: 'RUNNER_NOT_READY',
    message: 'Preflight checks failed. Check runner SSH, OpenCode, and provider env.',
    preflight_result: $json
  }
}];

// WAIT_FOR_BLUEPRINT Gate (dry-run compatible)
// In dry-run mode with blueprint_present=false, this is the target stop point.
// In real mode, this waits for a webhook callback with blueprint data.

if ($json.dry_run === true && $json.blueprint_present === false) {
  // MODE A: No blueprint, stop here
  return [{
    json: {
      status: 'WAIT_FOR_BLUEPRINT',
      gate_reached: true,
      message: 'Workflow reached WAIT_FOR_BLUEPRINT gate. No blueprint provided. Stopping safely.',
      dry_run: true,
      blueprint_present: false,
      timestamp: new Date().toISOString()
    }
  }];
}

// In dry-run mode with blueprint_present=true, pass through to validation
if ($json.dry_run === true && $json.blueprint_present === true) {
  // MODE B: Blueprint present, continue to validation
  return [{
    json: {
      ...$json,
      status: 'WAIT_FOR_BLUEPRINT',
      gate_reached: true,
      message: 'Workflow passed WAIT_FOR_BLUEPRINT gate. Blueprint present, proceeding to validation.',
      // Test blueprint data for dry-run
      body: {
        blueprint: 'Mini Task Tracker - A minimal task management application\n\nGoal: Create a simple task tracker with CRUD operations.\n\nFeatures:\n- Create tasks with title and description\n- List all tasks\n- Mark tasks as complete\n- Delete tasks\n\nExpected Outcome: A working CLI-based task tracker.\n\nRequirements:\n- Python 3.10+\n- SQLite database\n- Command-line interface\n\nAcceptance Criteria:\n- User can add a task\n- User can list all tasks\n- User can mark a task as done\n- User can delete a task'
      }
    }
  }];
}

// Real mode: pass through to WAIT node (original behavior)
return [$json];

const blueprint = String($json.body?.blueprint || $json.blueprint || $json.body || '').trim();

// Secret detection
const secretPatterns = [
  /sk-[A-Za-z0-9]{20,}/,
  /ghp_[A-Za-z0-9_]{20,}/,
  /github_pat_[A-Za-z0-9_]{20,}/,
  /Bearer\s+[A-Za-z0-9._\-]{20,}/,
  /-----BEGIN\s+[A-Z\s]+PRIVATE\s+KEY-----/,
  /eyJ[A-Za-z0-9_\-]{50,}/,
  /api_key\s*[=:]\s*[A-Za-z0-9]{20,}/i
];

const hasSecret = secretPatterns.some(p => p.test(blueprint));

// Content validation
const hasGoal = /(?:goal|ziel|problem|purpose|intent|objective)/i.test(blueprint);
const hasFunction = /(?:function|feature|software|application|app|program|tool|service|system)/i.test(blueprint);
const hasOutcome = /(?:outcome|result|expect|deliver|output|success)/i.test(blueprint);
const hasRequirements = /(?:requirement|story|need|must|should|shall|user|acceptance)/i.test(blueprint);
const contentLength = blueprint.length;
const contentSections = [hasGoal, hasFunction, hasOutcome, hasRequirements].filter(Boolean).length;

let status = 'BLUEPRINT_VALID';
if (hasSecret) status = 'RED_BLUEPRINT_SECRET';
else if (contentLength < 100) status = 'BLUEPRINT_EMPTY';
else if (contentSections < 3) status = 'BLUEPRINT_INCOMPLETE';
else if (contentSections < 5) status = 'BLUEPRINT_PARTIAL';

// Derive project slug
const firstLine = blueprint.split('\n')[0].replace(/^#+\s*/, '').trim();
const slug = firstLine
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 50) || 'blueprint-project';

return [{
  json: {
    ...$json,
    status: status,
    project_slug: slug,
    blueprint_length: contentLength,
    sections_found: contentSections,
    has_secret: hasSecret,
    blueprint_content: status === 'RED_BLUEPRINT_SECRET' ? '[REDACTED - SECRETS DETECTED]' : blueprint
  }
}];

return [{
  json: {
    status: $json.status,
    message: `Blueprint validation failed: ${$json.status}`,
    error: $json.status === 'RED_BLUEPRINT_SECRET' ? 'Secrets detected in blueprint. STOP.' : 'Blueprint incomplete. Resubmit with more detail.'
  }
}];

return [{
  json: {
    status: 'PIPELINE_COMPLETE',
    project_dir: $json.project_dir,
    project_slug: $json.project_slug,
    phases_completed: [
      'Runner Preflight',
      'WAIT_FOR_BLUEPRINT',
      'Blueprint Validation',
      'Project Folder Creation',
      'Spec Kit Init',
      'Git Init',
      'OpenCode Setup'
    ],
    next_steps: 'Run OpenCode Speckit phases in project directory',
    issue: '#19',
    timestamp: new Date().toISOString()
  }
}];

// Initialize state machine
const input = $input.first().json;
const state = {
  run_id: $execution.id,
  correlation_id: input.correlation_id || 'UNKNOWN',
  state: 'RECEIVED',
  previous_state: null,
  reason_code: 'INIT',
  timestamp: new Date().toISOString(),
  workflow_id: $workflow.id,
  execution_id: $execution.id,
  repository: null,
  issue_number: null,
  lock_generation: null,
  builder_ctid: 8001,
  task_id: 'ghiw_source_manifest_v1',
  artifact_sha256: null,
  mutation_approval_id: null
};
return {json: state};

// Input validation with forbidden field detection
const ALLOWED_SCHEMA_VERSION = '1.0';
const ALLOWED_OPERATIONS = ['contract-check', 'process-canary-issue'];
const ALLOWLISTED_REPOS = ['xxammaxx/n8n-blueprint-workflow'];
const SERVER_BUILDER_CTID = 8001;
const SERVER_BUILDER_ID = 'e3r6-canary-001';
const SERVER_TASK_ID = 'ghiw_source_manifest_v1';
const FORBIDDEN_FIELDS = [
  'url', 'repository_url', 'command', 'commands', 'shell', 'script',
  'args', 'argv', 'env', 'environment', 'credential', 'credential_id',
  'token', 'api_key', 'ssh_key', 'ctid', 'builder_ctid', 'builder_id',
  'workspace', 'path', 'working_directory', 'dry_run', 'max_fix_loops',
  'branch', 'commit', 'pull_request'
];
const KNOWN_FIELDS = ['schema_version', 'operation', 'repository', 'issue_number',
                      'correlation_id', 'mutation_approval_id', 'task_id'];
const state = $input.first().json;
const input = state.raw_input || $input.first().json;

for (const field of FORBIDDEN_FIELDS) {
  if (field in input) {
    state.state = 'REJECTED';
    state.reason_code = 'FORBIDDEN_FIELD';
    state.reason_detail = 'Field ' + field + ' is forbidden';
    return {json: state};
  }
}

for (const key of Object.keys(input)) {
  if (!KNOWN_FIELDS.includes(key)) {
    state.state = 'REJECTED';
    state.reason_code = 'UNKNOWN_FIELD';
    state.reason_detail = 'Unknown field: ' + key;
    return {json: state};
  }
}

if (!input.schema_version) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_SCHEMA_VERSION'; return {json: state};
}
if (input.schema_version !== ALLOWED_SCHEMA_VERSION) {
  state.state = 'REJECTED'; state.reason_code = 'INVALID_SCHEMA_VERSION'; return {json: state};
}
if (!input.operation) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_OPERATION'; return {json: state};
}
if (!ALLOWED_OPERATIONS.includes(input.operation)) {
  state.state = 'REJECTED'; state.reason_code = 'UNKNOWN_OPERATION'; return {json: state};
}
if (!input.repository) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_REPOSITORY'; return {json: state};
}
if (!ALLOWLISTED_REPOS.includes(input.repository)) {
  state.state = 'REJECTED'; state.reason_code = 'REPOSITORY_NOT_ALLOWLISTED'; return {json: state};
}
if (input.issue_number !== undefined) {
  if (!Number.isInteger(input.issue_number) || input.issue_number < 1) {
    state.state = 'REJECTED'; state.reason_code = 'INVALID_ISSUE_NUMBER'; return {json: state};
  }
}
if (!input.correlation_id) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_CORRELATION_ID'; return {json: state};
}
if (!/^GHIW-E4-[A-Za-z0-9_-]+$/.test(input.correlation_id)) {
  state.state = 'REJECTED'; state.reason_code = 'INVALID_CORRELATION_ID'; return {json: state};
}
if (!input.mutation_approval_id) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_MUTATION_APPROVAL_ID'; return {json: state};
}
if (input.task_id && input.task_id !== SERVER_TASK_ID) {
  state.state = 'REJECTED'; state.reason_code = 'INVALID_TASK_ID'; return {json: state};
}

state.state = 'INPUT_VALIDATED';
state.reason_code = 'VALIDATION_PASSED';
state.builder_ctid = SERVER_BUILDER_CTID;
state.builder_id = SERVER_BUILDER_ID;
state.task_id = SERVER_TASK_ID;
state.repository = input.repository;
state.issue_number = input.issue_number;
state.correlation_id = input.correlation_id;
state.mutation_approval_id = input.mutation_approval_id;
state.raw_input = input;

return {json: state};

// Path decision: contract-check vs process-canary-issue
const state = $input.first().json;
if (state.state !== 'INPUT_VALIDATED') {
  state.state = 'FAILED';
  state.reason_code = 'UNEXPECTED_STATE';
  return {json: state};
}
const operation = state.raw_input?.operation;
if (operation === 'contract-check') {
  state.state = 'CONTRACT_CHECK_COMPLETED';
  state.reason_code = 'CONTRACT_CHECK_PASSED';
  state.contract_check_result = {
    schema_version: '1.0',
    operation: 'contract-check',
    allowed_operations: ['contract-check', 'process-canary-issue'],
    builder_ctid: state.builder_ctid,
    builder_id: state.builder_id,
    task_id: state.task_id,
    allowlisted_repos: ['xxammaxx/n8n-blueprint-workflow'],
    canary_execution_authorized: false,
    contract_valid: true,
    checked_at: new Date().toISOString()
  };
} else if (operation === 'process-canary-issue') {
  state.state = 'INPUT_VALIDATED';
  state.reason_code = 'READY_FOR_CANARY_E4_R3';
  state.canary_authorized = false;
} else {
  state.state = 'REJECTED';
  state.reason_code = 'UNKNOWN_OPERATION';
}
return {json: state};
